export function drawCeviLogoVector(doc: PDFKit.PDFDocument, x: number, y: number, size: number) {
  const scale = size / 500;
  doc.save();
  doc.translate(x, y);
  doc.scale(scale);
  doc.path(CEVI_LOGO_PATH_RED).fill('#e20031');
  doc.path(CEVI_LOGO_PATH_BLUE).fill('#003d8f');
  doc.restore();
}

export function drawPfadiLogoVector(doc: PDFKit.PDFDocument, x: number, y: number, size: number) {
  const scale = size / 878;
  doc.save();
  doc.translate(x - 15 * scale, y - 23 * scale);
  doc.scale(scale);
  doc.path(PFADI_LOGO_PATH_GREEN).fill('#20553e');
  doc.path(PFADI_LOGO_PATH_ORANGE).fill('#f08a15');
  doc.path(PFADI_LOGO_PATH_NAVY).fill('#103353');
  doc.path(PFADI_LOGO_PATH_YELLOW).fill('#f9ad36');
  doc.restore();
}

export function drawVereinLogoVector(doc: PDFKit.PDFDocument, x: number, y: number, size: number) {
  const scale = size / 500;
  doc.save();
  doc.translate(x, y);
  doc.scale(scale);
  doc.roundedRect(75, 75, 350, 350, 90).fill('#2563eb');
  doc.roundedRect(135, 140, 230, 220, 30).fill('#ffffff');
  doc
    .path('M 135 170 C 135 153.43 148.43 140 165 140 L 335 140 C 351.57 140 365 153.43 365 170 L 365 200 L 135 200 Z')
    .fill('#ef4444');
  doc.roundedRect(180, 120, 24, 40, 12).fill('#1e293b');
  doc.roundedRect(296, 120, 24, 40, 12).fill('#1e293b');
  doc.roundedRect(227, 230, 45, 40, 10).fill('#10b981');
  doc.roundedRect(165, 290, 45, 40, 10).fill('#10b981');
  doc.restore();
}

export function drawJublaLogoVector(doc: PDFKit.PDFDocument, x: number, y: number, size: number) {
  const scale = size / 180;
  const offsetX = (size - 140 * scale) / 2;
  doc.save();
  doc.translate(x + offsetX, y);
  doc.scale(scale);
  doc.path(JUBLA_LOGO_COMPOUND_PATH).fill('#283583');
  doc.restore();
}

export function renderOrgLogoSvg(org: OrganizationType, x: number, y: number, size: number): string {
  if (org === 'CEVI') {
    const scale = size / 500;
    return `<g transform="translate(${x}, ${y}) scale(${scale})">
      <path d="${CEVI_LOGO_PATH_RED}" fill="#e20031" />
      <path d="${CEVI_LOGO_PATH_BLUE}" fill="#003d8f" />
    </g>`;
  }
  if (org === 'PFADI') {
    const scale = size / 878;
    return `<g transform="translate(${x - 15 * scale}, ${y - 23 * scale}) scale(${scale})">
      <path fill="#20553e" d="${PFADI_LOGO_PATH_GREEN}" />
      <path fill="#f08a15" d="${PFADI_LOGO_PATH_ORANGE}" />
      <path fill="#103353" d="${PFADI_LOGO_PATH_NAVY}" />
      <path fill="#f9ad36" d="${PFADI_LOGO_PATH_YELLOW}" />
    </g>`;
  }
  if (org === 'JUBLA') {
    const scale = size / 180;
    const offsetX = (size - 140 * scale) / 2;
    return `<g transform="translate(${x + offsetX}, ${y}) scale(${scale})">
      <path fill="#283583" d="${JUBLA_LOGO_COMPOUND_PATH}" />
    </g>`;
  }
  if (org === 'OTHER') {
    const scale = size / 500;
    return `<g transform="translate(${x}, ${y}) scale(${scale})">
      <rect x="75" y="75" width="350" height="350" rx="90" fill="#2563eb" />
      <rect x="135" y="140" width="230" height="220" rx="30" fill="#ffffff" />
      <path d="M 135 170 C 135 153.43 148.43 140 165 140 L 335 140 C 351.57 140 365 153.43 365 170 L 365 200 L 135 200 Z" fill="#ef4444" />
      <rect x="180" y="120" width="24" height="40" rx="12" fill="#1e293b" />
      <rect x="296" y="120" width="24" height="40" rx="12" fill="#1e293b" />
      <rect x="165" y="230" width="45" height="40" rx="10" fill="#3b82f6" opacity="0.2" />
      <rect x="227" y="230" width="45" height="40" rx="10" fill="#10b981" />
      <path d="M 240 250 L 246 256 L 260 242" stroke="#ffffff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" fill="none" />
      <rect x="290" y="230" width="45" height="40" rx="10" fill="#3b82f6" opacity="0.2" />
      <rect x="165" y="290" width="45" height="40" rx="10" fill="#10b981" />
      <path d="M 178 310 L 184 316 L 198 302" stroke="#ffffff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" fill="none" />
      <rect x="227" y="290" width="45" height="40" rx="10" fill="#3b82f6" opacity="0.2" />
      <rect x="290" y="290" width="45" height="40" rx="10" fill="#3b82f6" opacity="0.2" />
    </g>`;
  }
  return '';
}
